 "id": "semio-resp-symptoms",
 "subject": "semio",
 "group": "Respiratory",
 "title": "Respiratory clinical symptoms",
 "sourceFile": "Semiology 1 Clinical symptoms 2025.pdf (Respiratory semiology, Prof. Nahid Zaghba, 2025-2026)",
 "sourceUrl": "https://drive.google.com/file/d/11hD2xqj0f623VI52dAzzNdJRJyLMDRmZ/view?usp=drivesdk",
 "buildNote": "<strong>Built from the lecture slides.</strong> If your professor says something different, trust your professor.",
 "summary": [
  {
   "id": "s0",
   "title": "The big picture",
   "html": "<p>Five symptoms carry respiratory medicine: <strong>cough, sputum, vomica, hemoptysis, chest pain and dyspnoea</strong>. For each, the exam asks the same things: define it, analyse it (onset, duration, timing, triggers, appearance) and list the causes.</p>"
  },
  {
   "id": "s1",
   "title": "Cough",
   "html": "<p>A deep inspiration with an open glottis, then an explosive expiration: a defence reflex to clear the airways. Productive cough should be respected; useless dry cough treated.</p><div class='table-wrap'><table class='wide'><thead><tr><th scope='col'>Feature</th><th scope='col'>Value</th></tr></thead><tbody><tr><th scope='row'>Duration</th><td>Acute under 3 weeks; subacute 3 to 8; chronic over 8</td></tr><tr><th scope='row'>Nocturnal</th><td>GERD, asthma</td></tr><tr><th scope='row'>Morning</th><td>Bronchiectasis, chronic bronchitis</td></tr><tr><th scope='row'>Supine</th><td>GERD, left heart failure</td></tr><tr><th scope='row'>Bitonal</th><td>Recurrent nerve compression</td></tr><tr><th scope='row'>Painful</th><td>Pleural or parietal involvement</td></tr></tbody></table></div><p><strong>Chronic bronchitis:</strong> productive morning cough at least 3 months a year for 2 consecutive years. <strong>Dry chronic cough:</strong> cancer, interstitial disease, asthma, rhinosinusitis, GERD, <strong>ACE inhibitors</strong>, psychogenic. Complications: syncope, pneumothorax, rib fracture, incontinence, hernia, vomiting, insomnia.</p>"
  },
  {
   "id": "s2",
   "title": "Sputum and vomica",
   "html": "<p><strong>Sputum</strong> is abnormal subglottic secretion; over 30 mL/day is excessive, over <strong>100 mL/day bronchorrhoea</strong>. The mucociliary escalator is impaired in smokers, bronchiectasis, cystic fibrosis and ciliary dyskinesia.</p><div class='table-wrap'><table class='wide'><thead><tr><th scope='col'>Appearance</th><th scope='col'>Meaning</th></tr></thead><tbody><tr><th scope='row'>Purulent</th><td>Infection, abscess, bronchiectasis</td></tr><tr><th scope='row'>Frothy, pink</th><td>Acute pulmonary oedema</td></tr><tr><th scope='row'>Pearly</th><td>Asthma (Laennec)</td></tr><tr><th scope='row'>Foul smell</th><td>Anaerobes</td></tr><tr><th scope='row'>Haemoptoic</th><td>Same value as hemoptysis</td></tr></tbody></table></div><p>A <strong>vomica</strong> is a sudden coughing-up of pus. Clear: <strong>hydatid cyst</strong>. Pus with bile: liver abscess fistula. Chocolate: <strong>amoebic abscess</strong>.</p>"
  },
  {
   "id": "s3",
   "title": "Hemoptysis",
   "html": "<p>Blood from the lower airways coughed up. Every hemoptysis is an <strong>emergency</strong>, whatever the amount.</p><div class='table-wrap'><table class='wide'><thead><tr><th scope='col'></th><th scope='col'>Hemoptysis</th><th scope='col'>Haematemesis</th></tr></thead><tbody><tr><th scope='row'>History</th><td>Respiratory</td><td>Digestive</td></tr><tr><th scope='row'>Effort</th><td>Coughing</td><td>Vomiting</td></tr><tr><th scope='row'>Blood</th><td>Bright red, frothy</td><td>Dark, not aerated, food debris</td></tr></tbody></table></div><p>Low under 50 mL; medium 300 to 500 mL; high over 500 mL. Causes: cancer, tuberculosis, bronchiectasis, hydatid cyst, pneumonia, foreign body, valvulopathy, embolism; idiopathic in 15 percent.</p>"
  },
  {
   "id": "s4",
   "title": "Chest pain",
   "html": "<p>The lung is barely sensitive; the <strong>pleura, mediastinum and chest wall</strong> are very sensitive, via intercostal and phrenic nerves.</p><div class='table-wrap'><table class='wide'><thead><tr><th scope='col'>Cause</th><th scope='col'>Clue</th></tr></thead><tbody><tr><th scope='row'>Acute coronary syndrome</th><td>Retrosternal oppression to arms or jaw</td></tr><tr><th scope='row'>Pneumothorax</th><td>Sudden stabbing pain, easy on X-ray</td></tr><tr><th scope='row'>Aortic dissection</th><td>Intense pain to the back, hypertensive older man</td></tr><tr><th scope='row'>Pericarditis</th><td>Relieved sitting forward</td></tr><tr><th scope='row'>Pleurisy</th><td>Blocks inspiration, dry cough</td></tr><tr><th scope='row'>Oesophageal rupture</th><td>After vomiting, over 60</td></tr><tr><th scope='row'>Gallstones</th><td>Radiates to the right shoulder</td></tr></tbody></table></div>"
  },
  {
   "id": "s5",
   "title": "Dyspnoea",
   "html": "<p>Breathing discomfort; normal rate about <strong>16/min</strong>. Graded by <strong>NYHA</strong> and <strong>mMRC</strong>.</p><div class='table-wrap'><table class='wide'><thead><tr><th scope='col'>Type</th><th scope='col'>Meaning</th></tr></thead><tbody><tr><th scope='row'>Inspiratory</th><td>High (laryngotracheal) obstruction</td></tr><tr><th scope='row'>Expiratory</th><td>Low obstruction (asthma)</td></tr><tr><th scope='row'>Orthopnoea</th><td>Lying flat</td></tr><tr><th scope='row'>Platypnoea</th><td>On sitting up</td></tr><tr><th scope='row'>Paroxysmal nocturnal</th><td>Heart failure</td></tr><tr><th scope='row'>Postprandial</th><td>GERD, aspiration, food allergy</td></tr></tbody></table></div><p>Acute causes: laryngeal, asthma, pneumonia, pneumothorax, embolism, pulmonary oedema. Chronic: COPD, asthma, bronchiectasis, tuberculosis, sarcoidosis, chronic pleurisy, left heart disease.</p>"
  }
 ],
