 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "Give the four steps of the chest exam.",
   "back": "After the interview: inspection, palpation, percussion and auscultation; the signs are grouped into syndromes, then further tests lead to the diagnosis."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "How is inspection done?",
   "back": "Naked chest, patient seated or standing, in full light, watching the patient undress for dyspnoea, inspecting the whole thorax. Note general appearance: pallor, cyanosis, dyspnoea, thinness, oedema."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "Describe abnormal thorax shapes.",
   "back": "Barrel chest: bilateral distension (emphysema, asthma). Unilateral distension: pleurisy, parietal tumour. Retraction: unilateral, or whole (pachypleuritis). Deformities: pectus excavatum, carinatum, arcuatum. Spine: kyphosis, lordosis, scoliosis."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "Give respiratory rates.",
   "back": "Adults 12 to 20/min; infants and neonates 30 to 60/min. Polypnoea over 20; bradypnoea under 12. Also note inspiration and expiration duration, stridor or wheeze, and expansion."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "List the signs of increased work of breathing.",
   "back": "Tripod position; accessory muscle use (sternocleidomastoid, scalenes); nasal flaring; intercostal, subcostal, suprasternal and supraclavicular retractions; grunting; pursed lips; expiratory abdominal contraction; paradoxical thoracoabdominal breathing."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "Name cutaneous and peripheral signs.",
   "back": "Malar redness, Horner signs, herpes, scars, tattoos, oedema, jugular venous distension, collateral circulation, cyanosis, eczema, erythema nodosum, joint deformities, superior vena cava swelling of face and arms, wall masses."
  },
  {
   "id": "c6",
   "type": "text",
   "front": "Describe digital clubbing and its tests.",
   "back": "Nails enlarged and curved (Hippocratic), with swollen distal phalanges: chronic hypoxaemia. Lovibond angle of 180 degrees or more. Schamroth test: the diamond window between opposed nails disappears."
  },
  {
   "id": "c7",
   "type": "text",
   "front": "What is Pierre Marie hypertrophic osteoarthropathy?",
   "back": "A hereditary or paraneoplastic syndrome: painful clubbing, hypertrophy of extremities with synovial effusions, vasomotor disorders, arthralgia, and radiological periostitis of long bones."
  },
  {
   "id": "c8",
   "type": "text",
   "front": "What is Horner's syndrome?",
   "back": "Disruption of the sympathetic pathway to one side of the face: miosis, ptosis with apparent enophthalmos, and anhidrosis."
  },
  {
   "id": "c9",
   "type": "text",
   "front": "How is palpation done, and what does fremitus show?",
   "back": "Warm hands, seated patient, bilateral and symmetrical; the patient says toy boat (44 in Arabic, 33 in French). Fremitus is increased in pneumonia; decreased or abolished in pleurisy, pneumothorax, atelectasis and emphysema bullae. Palpation also finds painful points, subcutaneous emphysema, masses, nodes and expansion."
  },
  {
   "id": "c10",
   "type": "text",
   "front": "How is percussion done, and what does it show?",
   "back": "The middle finger of the dominant hand strikes the distal joint of the other hand's middle finger on an intercostal space, comparing both sides at each level. Normal lung is resonant; liver and heart dull. Dull: pleurisy, pachypleuritis, consolidation. Hyperresonant: pneumothorax, emphysema."
  },
  {
   "id": "c11",
   "type": "text",
   "front": "Describe normal breath sounds.",
   "back": "Vesicular: parenchymal noise over both lungs, mainly inspiration and early expiration. Bronchial: loud, high-pitched, over the sternum. Tracheal: very loud, over the neck, in both phases."
  },
  {
   "id": "c12",
   "type": "text",
   "front": "When are breath sounds reduced or absent?",
   "back": "Generalised: upper airway obstruction, advanced emphysema, severe asthma. Localised to one side: pleural effusion, pneumothorax, hydropneumothorax, main bronchus obstruction, tumour, pneumonia or collapse."
  },
  {
   "id": "c13",
   "type": "text",
   "front": "Describe the added sounds.",
   "back": "Wheeze: whistling from narrowed airways. Rhonchi: low-pitched snoring. Crackles: coarse (rice krispies: fluid, infection) or fine (velcro: fluid, infection, fibrosis). Rub: end-inspiratory, foot in fresh snow. Stridor: loud inspiratory monophonic wheeze of upper airway obstruction."
  },
  {
   "id": "c14",
   "type": "text",
   "front": "Summarise the common syndromes.",
   "back": "Consolidation: dull, bronchial breathing, coarse crackles, increased vocal resonance. Effusion: dull, absent breath sounds, possible rub, decreased resonance. Pneumothorax: hyperresonant, absent sounds, decreased resonance. Fibrosis and pulmonary oedema: normal percussion, fine crackles."
  },
  {
   "id": "c15",
   "type": "text",
   "front": "What does the general exam add?",
   "back": "Cardiovascular: right heart failure, pericarditis (report in pleurisy). Abdominal: ascites, hepato- or splenomegaly (report in pleurisy). ENT infection. Lymph nodes (tuberculosis, lymphoma, sarcoidosis). Urogenital and pelvic. Neurological: meningeal signs in tuberculosis, pleurisy or miliary."
  }
 ],
 "deeper": [
  {
   "title": "Why effusion and consolidation both sound dull but feel different",
   "html": "<p>Both fluid in the pleura and a solid, infected lung block the air that normally makes the chest resonant, so both are dull. But solid lung conducts voice vibrations well, so fremitus and vocal resonance rise, while fluid between lung and wall damps them. That single palpation step separates the two at the bedside.</p><p class='src'>Source: the lecture's palpation, percussion and summary table.</p>"
  },
  {
   "title": "Why clubbing sends you looking for lung cancer",
   "html": "<p>Clubbing reflects chronic hypoxaemia or certain chronic diseases, and when it becomes painful with periostitis (Pierre Marie osteoarthropathy) it is often paraneoplastic. A smoker with new clubbing needs a chest X-ray.</p><p class='src'>Source: the lecture's clubbing and osteoarthropathy slides.</p>"
  }
 ],
