   "q": "What is heart failure?",
   "options": [
    "The heart pumps poorly",
    "The heart stops",
    "The valves calcify",
    "The pericardium fills"
   ],
   "answer": 0,
   "why": "The heart muscle does not pump blood as well as it should; blood backs up and fluid builds in the lungs.",
