 "summary": [
  {
   "id": "s0",
   "title": "The big picture",
   "html": "<p>An arrhythmia is an irregular rhythm. The one to know is <strong>atrial fibrillation</strong>: the commonest significant arrhythmia, and a major cause of <strong>stroke</strong>.</p>"
  },
  {
   "id": "s1",
   "title": "Normal conduction and the ECG",
   "html": "<p>SA node, atria, AV node, bundle of His, Purkinje fibres, ventricles.</p><div class='table-wrap'><table class='wide'><thead><tr><th scope='col'>Wave</th><th scope='col'>Meaning</th></tr></thead><tbody><tr><th scope='row'>P</th><td>Atrial depolarisation (right atrium first)</td></tr><tr><th scope='row'>QRS</th><td>Ventricular depolarisation, 0.08 to 0.12 s</td></tr><tr><th scope='row'>T</th><td>Ventricular repolarisation</td></tr></tbody></table></div>"
  },
  {
   "id": "s2",
   "title": "Atrial fibrillation",
   "html": "<p>Almost <strong>59 million</strong> people in 2019. The sinus node is inhibited; chaotic re-entrant wavelets drive the atria. Causes: hypertension, coronary disease, <strong>mitral valve disease</strong>, heart failure, cardiomyopathy. Symptoms: palpitations, flutters, chest pain, dyspnoea, fatigue, dizziness, confusion, or none.</p><p>Clots form in the <strong>left atrial appendage</strong> and embolise: <strong>stroke risk about five-fold</strong>. Management: stroke prevention, rhythm control, ablation, appendage occlusion.</p>"
  },
  {
   "id": "s3",
   "title": "Flutter versus fibrillation",
   "html": "<p><div class='table-wrap'><table class='wide'><thead><tr><th scope='col'></th><th scope='col'>Atrial flutter</th><th scope='col'>Atrial fibrillation</th></tr></thead><tbody><tr><th scope='row'>Activity</th><td>Organised re-entrant circuit</td><td>Chaotic</td></tr><tr><th scope='row'>Atrial rate</th><td>250 to 350</td><td>350 to 600</td></tr><tr><th scope='row'>Ventricles</th><td>Often regular</td><td>Irregularly irregular</td></tr><tr><th scope='row'>ECG</th><td>Sawtooth F waves</td><td>No P waves</td></tr><tr><th scope='row'>Stroke risk</th><td>Increased</td><td>High</td></tr><tr><th scope='row'>Prevalence</th><td>2 to 6 million</td><td>50 to 60 million</td></tr></tbody></table></div></p>"
  }
 ],
