 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "Define arrhythmia and give AFib numbers.",
   "back": "An irregular heart rhythm. Atrial fibrillation is the most common significant arrhythmia: 33.5 million in 2010, almost 59 million in 2019, projected to rise over 60 percent by 2050."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "List arrhythmia symptoms.",
   "back": "Cardiac: chest pain, tachycardia, irregular heartbeat, flutters, leg swelling (right heart failure). General: fatigue even after rest, stress, dizziness or faintness, confusion. Some patients have no symptoms."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "Describe normal cardiac conduction.",
   "back": "Depolarisation starts in the SA node pacemaker cells, spreads through the atria, passes the AV node, then the bundle of His and Purkinje fibres through the ventricles. This orderly sequence produces the ECG."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "Describe the ECG waves.",
   "back": "The ECG plots voltage against time. P wave: atrial depolarisation, right atrium slightly before left. QRS: near-simultaneous ventricular depolarisation, 0.08 to 0.12 s; longer is wide. T wave: ventricular repolarisation."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "What happens in atrial fibrillation?",
   "back": "The sinus node is inhibited; migrating wavelets of re-entrant activation replace coordinated atrial activity, sending irregular impulses to the AV node."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "What causes AFib?",
   "back": "Structural heart disease: hypertension (atrial enlargement and fibrosis), coronary artery disease (ischaemia, scarring), valvular disease (especially mitral), heart failure and cardiomyopathy."
  },
  {
   "id": "c6",
   "type": "text",
   "front": "Why does AFib cause strokes?",
   "back": "Blood stagnates in the left atrial appendage (Virchow's triad), clots form and embolise to the cerebral arteries. Stroke risk rises about five-fold; stroke can also cause AFib."
  },
  {
   "id": "c7",
   "type": "text",
   "front": "Atrial flutter versus fibrillation.",
   "back": "Flutter: organised re-entrant circuit, atrial rate 250 to 350, often regular ventricular response, sawtooth F waves, milder symptoms, increased stroke risk. AFib: chaotic, 350 to 600, irregularly irregular, no P waves, high stroke risk. Prevalence about 9 to 1, both rising with age."
  },
  {
   "id": "c8",
   "type": "text",
   "front": "How is AFib managed?",
   "back": "The ABC pathway: stroke prevention (anticoagulation), rhythm control, cardiac ablation, and left atrial appendage occlusion when treatment fails."
  }
 ],
 "deeper": [
  {
   "title": "Why an irregularly irregular pulse matters",
   "html": "<p>A pulse with no pattern at all is the bedside sign of atrial fibrillation, which may otherwise be silent. Because AFib multiplies stroke risk, feeling for irregularity in every patient's pulse is one of the cheapest stroke-prevention tools in medicine.</p><p class='src'>Source: the lecture's AFib symptoms and stroke slides.</p>"
  }
 ],
