 "id": "semio-cv-revision",
 "subject": "semio",
 "group": "Cardiovascular",
 "title": "Cardiovascular revision",
 "sourceFile": "Cardiovascular Semiology 6 (Revision).pdf (Pr. Anh Tuan Dinh Xuan, 2025-2026)",
 "sourceUrl": "https://drive.google.com/file/d/1sgowHuS3Vb8i0Bzwooek-Jiw3-ji0P2V/view?usp=drivesdk",
 "buildNote": "<strong>Built from the revision slides.</strong> This lecture reviews heart failure and angina, covered in full on their own pages, and adds haemodynamics, coronary flow, endothelial dysfunction and the global burden of cardiovascular disease. If your professor says something different, trust your professor.",
 "summary": [
  {
   "id": "s0",
   "title": "The big picture",
   "html": "<p>This revision lecture ties together heart failure and angina, and adds three ideas: the <strong>flow equation</strong>, <strong>endothelial dysfunction</strong> as the start of coronary disease, and the <strong>global burden</strong> of cardiovascular disease.</p>"
  },
  {
   "id": "s1",
   "title": "Haemodynamics and the coronaries",
   "html": "<p><strong>Q = ΔP / R</strong>: raise resistance at the same pressure and flow falls. Left coronary flow happens mainly in <strong>diastole</strong>.</p><p>The endothelium makes <strong>nitric oxide</strong>, which relaxes smooth muscle. Risk factors cause <strong>endothelial dysfunction</strong>: less NO, oxidative stress, inflammation, leucocyte adhesion and vasoconstriction (endothelin-1, angiotensin II, thromboxane A2), leading to atherosclerosis, plaque rupture and atherothrombosis.</p>"
  },
  {
   "id": "s2",
   "title": "Heart failure and angina recap",
   "html": "<p><div class='table-wrap'><table class='wide'><thead><tr><th scope='col'>Condition</th><th scope='col'>Key points</th></tr></thead><tbody><tr><th scope='row'>Systolic HF</th><td>Can't pump, thin chambers</td></tr><tr><th scope='row'>Diastolic HF</th><td>Can't fill, stiff chambers</td></tr><tr><th scope='row'>Left HF</th><td>Pulmonary oedema, orthopnoea, PND, crackles</td></tr><tr><th scope='row'>Right HF</th><td>JVD, hepatosplenomegaly, ascites, pitting oedema</td></tr><tr><th scope='row'>Stable angina</th><td>Exertional, relieved by rest, ST depression</td></tr><tr><th scope='row'>Unstable angina</th><td>Clot on plaque, rest pain, emergency</td></tr><tr><th scope='row'>Prinzmetal</th><td>Spasm, any time, ST elevation</td></tr></tbody></table></div></p>"
  },
  {
   "id": "s3",
   "title": "Global burden",
   "html": "<p>Cardiovascular disease is the <strong>leading cause of death</strong> worldwide, about <strong>17.7 million</strong> a year, though in high-income countries <strong>cancer kills twice as many</strong>. Over <strong>70 percent</strong> is caused by <strong>modifiable risk factors</strong>: hypertension, diabetes, cholesterol, waist-to-hip ratio, tobacco, alcohol, poor diet, low activity, air pollution, depression. Poor diet, low education, air pollution and low strength matter most in low-income countries, so prevention must be tailored locally.</p>"
  }
 ],
