 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "Which digestive organs can be examined?",
   "back": "The mouth, the stomach, small intestine and colon, the anal region and lower rectum, and partly the liver and spleen."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "How do you prepare for the exam?",
   "back": "Check identity, explain and obtain consent, ensure an intimate, calm, warm room; patient lying flat, doctor on the patient's right."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "What do you look for in the mouth?",
   "back": "Teeth, gums, palate, cheeks, tongue, tonsils and uvula. Aphthous ulcers (IBD), atrophic glossitis (B12 deficiency), white plaques (candidiasis), angular cheilitis (iron deficiency)."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "What does the neck exam include?",
   "back": "Cervical lymph nodes, especially the left supraclavicular node (digestive cancer metastasis), thyroid (moves with swallowing), vascular auscultation. The oesophagus cannot be examined directly."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "What does abdominal inspection look for?",
   "back": "Surgical scars, hernia or eventration (hernia on a scar), collateral veins (portal hypertension), bulges or asymmetry, and skin lesions."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "How is palpation done?",
   "back": "Supine, knees bent to relax the muscles; light then deep palpation of all quadrants with one or two hands, looking for masses, tenderness, pain, hepatomegaly and splenomegaly."
  },
  {
   "id": "c6",
   "type": "text",
   "front": "How are liver and spleen palpated?",
   "back": "Liver: under the right ribs, flat hand or hooked fingertips, with a deep breath that lowers the liver. Spleen: deep under the left ribs, hard to feel when normal; splenomegaly is easy and moves with breathing."
  },
  {
   "id": "c7",
   "type": "text",
   "front": "Describe percussion and auscultation.",
   "back": "Percussion: tympany means air, dullness means dense organ or fluid; the abdomen is tympanic except over the liver and a full bladder. Auscultation: bowel sounds and arterial bruits, such as an aortic aneurysm."
  },
  {
   "id": "c8",
   "type": "text",
   "front": "How is the proctological exam done?",
   "back": "Explain and obtain consent in a private room; knee-chest or lateral (Sims) position; gloves and lubricant; inspect the anal skin, then digital exam of the anal canal, distal rectum and prostate."
  }
 ],
 "deeper": [
  {
   "title": "Why the left supraclavicular node matters",
   "html": "<p>Lymph from the abdomen drains via the thoracic duct, which empties near the left supraclavicular region. A hard node there can be the first sign of a stomach or other digestive cancer that has spread, so it is always felt during a digestive exam.</p><p class='src'>Source: the lecture's cervical examination slide, with standard anatomy.</p>"
  }
 ],
