 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "Define jaundice.",
   "back": "Excess bilirubin, typically above 35 µmol/L, causing yellow sclera and/or skin. A symptom of many diseases, needing a structured aetiological strategy based on bilirubin metabolism."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "What is bilirubin?",
   "back": "A pigment from haemoglobin breakdown, eliminated in bile, responsible for urine and stool colour."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "List cholestasis symptoms.",
   "back": "Pruritus, dark urine, pale (acholic) stools, steatorrhoea, xanthoma and xanthelasma, and signs of fat-soluble vitamin (A, D, E, K) deficiency."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "Give the lab findings of cholestasis.",
   "back": "Raised conjugated bilirubin, GGT, alkaline phosphatase, cholesterol and 5'-nucleotidase; prolonged prothrombin time (ratio under 70 percent)."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "What history matters in jaundice?",
   "back": "Age, sex, occupation, chronic liver disease, liver or biliary surgery, autoimmune disease, viral hepatitis risk factors, travel, alcohol, smoking, drug use, medications and supplements, family history of jaundice or cancer."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "What symptoms and signs do you look for?",
   "back": "Onset and course of jaundice, cholestasis symptoms, fever, pain, dyspepsia, GI bleeding, diarrhoea, neurological signs, weight loss, joint pain; acute cholangitis = pain, fever, jaundice. Exam: GCS, asterixis, fetor hepaticus, oedema, sclera, scratch marks, purpura, spider angiomas, palmar erythema, gynaecomastia, tattoos, abdomen, rectum, nodes."
  },
  {
   "id": "c6",
   "type": "text",
   "front": "Which tests are used?",
   "back": "Blood count and smear, prothrombin time, liver function tests, protein electrophoresis, iron studies, haemolysis tests (LDH, haptoglobin, Coombs, Hb electrophoresis), autoimmune and viral serology, infection tests. Imaging: ultrasound, CT, MRI, endoscopic ultrasound, biopsy; ERCP is therapeutic."
  },
  {
   "id": "c7",
   "type": "text",
   "front": "Give the aetiological strategy.",
   "back": "First: cholestatic (conjugated) or not (unconjugated). Cholestatic: ultrasound for dilated ducts: yes = extrahepatic obstruction (e.g. biliary stones), no = intrahepatic (e.g. chronic liver disease). Non-cholestatic: think haemolysis, corpuscular (usually extravascular) or extracorpuscular (usually intravascular)."
  }
 ],
 "deeper": [
  {
   "title": "Why urine darkens but stools pale",
   "html": "<p>In obstruction, conjugated bilirubin cannot reach the gut, so stools lose their colour. Being water-soluble, it spills into the blood and is filtered into urine, which darkens. Unconjugated bilirubin in haemolysis is bound to albumin and does not reach urine.</p><p class='src'>Source: the lecture's cholestasis slides, with standard physiology.</p>"
  }
 ],
