 "id": "semio-gi-hepatomegaly",
 "subject": "semio",
 "group": "Digestive",
 "title": "Hepatomegaly",
 "sourceFile": "Hepatomegaly.pdf (Digestive semiology, Pr. Wafaa Khannoussi)",
 "sourceUrl": "https://drive.google.com/file/d/1A75ah23W1U76a82QA19w9AER04VCTugP/view?usp=drivesdk",
 "buildNote": "<strong>Built from the lecture slides.</strong> If your professor says something different, trust your professor.",
 "summary": [
  {
   "id": "s0",
   "title": "The big picture",
   "html": "<p>Hepatomegaly is diagnosed by the examining hand. How the liver <strong>feels</strong> (soft or hard, smooth or nodular, painful or not) points to the cause; <strong>ultrasound</strong> confirms.</p>"
  },
  {
   "id": "s1",
   "title": "Examination",
   "html": "<p>Palpate the lower border with deep inspiration and hooked fingers; percuss the upper limit from above; measure on the midclavicular line: normal <strong>under 12 cm</strong>. Normal liver: firm, regular, smooth, painless.</p><p><strong>Differential:</strong> left: stomach, transverse colon, pancreas; right: liver ptosis, <strong>Riedel lobe</strong>, colon, right kidney, gallbladder.</p>"
  },
  {
   "id": "s2",
   "title": "Clinical orientation",
   "html": "<p><div class='table-wrap'><table class='wide'><thead><tr><th scope='col'>Cause</th><th scope='col'>Consistency</th><th scope='col'>Surface</th><th scope='col'>Pain</th></tr></thead><tbody><tr><th scope='row'>Cirrhosis</th><td>Firm to hard</td><td>Nodular, irregular</td><td>Absent</td></tr><tr><th scope='row'>Cardiac</th><td>Soft to firm</td><td>Smooth</td><td>Present</td></tr><tr><th scope='row'>Cholestasis, storage</th><td>Firm or soft</td><td>Smooth</td><td>Absent</td></tr><tr><th scope='row'>Neoplastic</th><td>Hard</td><td>Nodular</td><td>Present</td></tr><tr><th scope='row'>Abscess</th><td>Firm</td><td>Smooth</td><td>Intense</td></tr></tbody></table></div></p>"
  },
  {
   "id": "s3",
   "title": "Causes and clues",
   "html": "<p>Tumours (adenoma, cysts, metastasis, HCC, lymphoma), metabolic (steatosis, Wilson's, haemochromatosis, Gaucher), congestion (heart failure, Budd-Chiari), inflammatory (hepatitis B and C, abscess, drugs, alcohol), cirrhosis.</p><div class='table-wrap'><table class='wide'><thead><tr><th scope='col'>Clue</th><th scope='col'>Think of</th></tr></thead><tbody><tr><th scope='row'>+ splenomegaly + collaterals</th><td>Cirrhosis, portal hypertension</td></tr><tr><th scope='row'>+ RUQ pain + fever</th><td>Abscess</td></tr><tr><th scope='row'>+ poor PS + lower GI bleeding</th><td>Colorectal cancer metastases</td></tr><tr><th scope='row'>Painful + hepatojugular reflux</th><td>Heart failure</td></tr><tr><th scope='row'>+ neurological signs</th><td>Wilson's disease</td></tr></tbody></table></div>"
  }
 ],
