 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "Define hepatomegaly.",
   "back": "Enlargement of the whole liver or part of it. Diagnosis is clinical; the cause needs additional work-up."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "How is hepatomegaly examined?",
   "back": "Inspection for a right hypochondrial bulge; palpation of the anteroinferior border with deep inspiration and hooked fingers, plus percussion and auscultation. The upper limit by percussion from above; measure on the midclavicular line (normal under 12 cm). Left liver: palpation and percussion in the epigastrium."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "How do you describe the liver?",
   "back": "Normal: firm, regular border, smooth surface, painless. Abnormal: too soft or hard, sharp or irregular border, nodular surface, painful."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "What is the differential diagnosis?",
   "back": "Left: masses of the stomach, transverse colon or pancreatic body. Right: liver ptosis, Riedel lobe, masses of the right colic flexure or right kidney, enlarged gallbladder."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "Link liver features to causes.",
   "back": "Cirrhosis: firm to hard, irregular sharp border, nodular, painless. Cardiac: soft to firm, smooth, painful. Cholestasis or storage: firm or soft, smooth, painless. Neoplastic: hard, nodular, painful. Abscess: localised, smooth, intensely painful."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "List the causes of hepatomegaly.",
   "back": "Tumours: benign (adenoma, cysts), malignant (metastasis, lymphoma, haemopathy, HCC). Metabolic: steatosis, Wilson's, haemochromatosis, Gaucher. Congestion: heart failure, Budd-Chiari. Inflammatory: HBV, HCV, sepsis, abscess, drugs, alcohol, granulomatosis, systemic disease. Cirrhosis, portal vein thrombosis."
  },
  {
   "id": "c6",
   "type": "text",
   "front": "Match the clinical clues.",
   "back": "HMG + splenomegaly + collaterals: cirrhosis with portal hypertension. HMG + right upper quadrant pain + fever: abscess. HMG + poor performance status + lower GI bleeding: colorectal cancer with metastases. Painful HMG + hepatojugular reflux: heart failure. HMG + neurological signs: Wilson's disease."
  }
 ],
 "deeper": [
  {
   "title": "Why the congested liver hurts but the cirrhotic one does not",
   "html": "<p>Pain comes from stretching of the liver capsule. Acute congestion in heart failure swells the liver quickly, stretching the capsule and causing pain. Cirrhosis develops slowly, with scarring and nodules, so the capsule is not suddenly stretched and the liver is usually painless.</p><p class='src'>Source: the lecture's clinical orientation table, with standard pathophysiology.</p>"
  }
 ],
