 "id": "semio-gi-constipation",
 "subject": "semio",
 "group": "Digestive",
 "title": "Constipation",
 "sourceFile": "constipation.pdf (Digestive semiology, Pr. Wafaa Khannoussi and Dr Afafe Taiymi)",
 "sourceUrl": "https://drive.google.com/file/d/1bHsRD8ZAGBsCRqGVZtIzEuQY1ZwDV10g/view?usp=drivesdk",
 "buildNote": "<strong>Built from the lecture slides.</strong> If your professor says something different, trust your professor.",
 "summary": [
  {
   "id": "s0",
   "title": "The big picture",
   "html": "<p>Constipation is easy to diagnose; the work is finding the cause. First rule out a <strong>secondary</strong> (organic) cause, especially when there are <strong>red flags</strong>; then type a <strong>primary</strong> constipation as slow transit or outlet dysfunction.</p>"
  },
  {
   "id": "s1",
   "title": "Definition and mechanisms",
   "html": "<p><strong>Fewer than 3 stools a week</strong>, under <strong>100 g/day</strong>, hard stools.</p><div class='table-wrap'><table class='wide'><thead><tr><th scope='col'>Type</th><th scope='col'>Mechanism</th><th scope='col'>Causes</th></tr></thead><tbody><tr><th scope='row'>Slow transit</th><td>Reduced colonic motility</td><td>Colonic inertia, spastic colon</td></tr><tr><th scope='row'>Outlet dysfunction</th><td>Pelvic floor fails to relax</td><td>Anismus, megarectum, rectocele, internal prolapse</td></tr><tr><th scope='row'>Secondary</th><td>Underlying disease</td><td>Tumour, hypothyroidism, diabetes, Parkinson's, opioids, iron</td></tr></tbody></table></div>"
  },
  {
   "id": "s2",
   "title": "Assessment",
   "html": "<p>History of drugs, diet, surgery, family cancer. Exam: absent bowel sounds (ileus) versus hyperactive (obstruction). <strong>Digital rectal exam</strong>: impaction, tone, masses, pelvic floor.</p><p><strong>Red flags:</strong> rectal bleeding, weight loss, anaemia, severe pain, family history of colorectal cancer or IBD.</p>"
  },
  {
   "id": "s3",
   "title": "Work-up",
   "html": "<p>Organic: colonoscopy, CT or MRI, blood count, thyroid, calcium and potassium, glucose, coeliac serology. Functional: colonic transit, defecography, <strong>anorectal manometry</strong> for outlet dysfunction. <strong>IBS-C</strong>: pain and bloating without organic disease.</p>"
  }
 ],
 "exam": [
  "Constipation: under 3 stools/week, under 100 g/day, hard stools.",
  "Primary: slow transit or outlet dysfunction.",
  "Outlet: pelvic floor fails to relax (anismus).",
  "Absent bowel sounds: ileus; hyperactive: obstruction.",
  "Red flags: bleeding, weight loss, anaemia, family history.",
  "Causes: hypothyroidism, hypercalcaemia, opioids, iron.",
  "Anorectal manometry: dyssynergic defecation."
 ],
