 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "Define constipation.",
   "back": "Three angles: clinical, fewer than 3 stools a week; quantitative, under 100 g/day; qualitative, hard dehydrated stools. One of the commonest GI complaints."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "Primary versus secondary constipation.",
   "back": "Primary (functional): often chronic and isolated, by slow transit or outlet dysfunction. Secondary: more recent, a symptom of an underlying digestive or non-digestive condition."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "Explain slow transit and outlet dysfunction.",
   "back": "Slow transit: delayed movement through the colon, from reduced motility or spasticity, enteric nerve disorders. Outlet dysfunction: poor rectal propulsion or high resistance, e.g. the pelvic floor failing to relax, causing incomplete evacuation."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "What other mechanisms contribute?",
   "back": "Stool dehydration from slow transit; neurogenic and myogenic hypomotility; hormonal and metabolic factors such as thyroid hormones and cortisol."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "What history matters?",
   "back": "Chronic digestive disease, diabetes, neurological disorders; risk factors (age, low-fibre diet, sedentary life, pregnancy); surgery; medications (opioids, iron); family history of colorectal cancer. Characteristics: duration, frequency, straining, stool form, incomplete evacuation, blockage sensation, manual manoeuvres, laxatives."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "Describe the examination.",
   "back": "Weight and nutrition. Abdomen: distension, tenderness, masses; absent sounds (ileus) or hyperactive (obstruction); tympany or faecal dullness. Rectal: squatting and straining for prolapse, knee-chest or left lateral; inspect for haemorrhoids, fissures, fistulas; feel impaction, tone and masses. Pelvic and neurological exams as needed."
  },
  {
   "id": "c6",
   "type": "text",
   "front": "When and how is constipation investigated?",
   "back": "Indications: persistent constipation, failed treatment, need to type it, red flags (bleeding, weight loss, anaemia, severe pain, family history). Organic work-up: colonoscopy, CT or MRI, blood count, thyroid, electrolytes (calcium, potassium), glucose, coeliac serology. Functional: colonic transit study, defecography, anorectal manometry."
  },
  {
   "id": "c7",
   "type": "text",
   "front": "List the causes.",
   "back": "Secondary: colorectal tumours, strictures, megacolon, compression, fissures, prolapse, haemorrhoids; Parkinson's, MS, spinal cord injury, stroke; hypothyroidism, diabetes, hypercalcaemia, hypokalaemia, CKD; opioids, antidepressants, antihistamines, iron. Primary: slow transit (colonic inertia, spastic colon) or outlet (anismus, megarectum, rectocele, internal prolapse). IBS-C: pain, bloating, no organic cause."
  }
 ],
 "deeper": [
  {
   "title": "Why new constipation in an older adult is taken seriously",
   "html": "<p>A change in bowel habit late in life may be the first sign of colorectal cancer narrowing the colon. That is why new-onset constipation, especially with bleeding, weight loss or anaemia, prompts colonoscopy rather than just laxatives.</p><p class='src'>Source: the lecture's red flags and work-up slides.</p>"
  }
 ],
