 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "Define nausea and vomiting.",
   "back": "Nausea: unpleasant, subjective sensation often with the urge to vomit, from the GI tract or the CNS. Vomiting (emesis): forceful expulsion of stomach contents through the mouth, usually preceded by nausea; active mechanism of violent cyclic contractions of the abdominal muscles, diaphragm and respiratory muscles."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "Describe the pathophysiology of vomiting.",
   "back": "Stimuli (GI irritation, vestibular disturbances, higher cortical centres, CTZ stimulation by drugs or toxins) activate the vomiting centre, then the abdominal vagal afferents. The diaphragm and abdominal muscles contract strongly and the LES relaxes: forceful ejection of stomach contents through the mouth."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "What do you ask in the history?",
   "back": "Age; medical and surgical history, especially digestive; medications (type, dose, date of last intake); toxic exposure; recent travel; similar cases in family or close contacts; last menstrual period and contraception."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "Which characteristics of vomiting do you describe?",
   "back": "Onset and duration (acute, chronic, recurrent), circumstances (spontaneous or induced), frequency, content, volume, triggers and relieving factors (diet, head position), pattern and timing, impact (appetite, hydration, weight, general condition)."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "What does the timing of vomiting suggest?",
   "back": "Morning: pregnancy or alcohol dependence. Early postprandial: gastric emptying disorder or gastroparesis. Late postprandial: duodenal or pyloric obstruction. During meals: psychogenic cause."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "What does the content of vomit suggest?",
   "back": "Clear fluid: acid reflux or regurgitation. Undigested food: gastroparesis or gastric outlet obstruction. Bile: bile reflux. Blood (haematemesis): active upper GI bleeding. Feculent: severe bowel obstruction."
  },
  {
   "id": "c6",
   "type": "text",
   "front": "What are the associated symptoms?",
   "back": "Nausea, abdominal pain, diarrhoea, myalgias, fever; extra-digestive: headache, photophobia (meningeal syndrome), altered consciousness."
  },
  {
   "id": "c7",
   "type": "text",
   "front": "Describe the physical examination.",
   "back": "General: dehydration (dry mucosae, reduced skin turgor, sunken eyes), vital signs, temperature. Abdomen: distension, scars, tenderness, masses, bowel sounds (hyperactive: obstruction; absent: ileus), percussion for ascites or mass. Neurological: headache, papilledema (raised ICP); altered mental status, dizziness, nystagmus (CNS). Cardiovascular: heart failure. Lymph nodes: infection or malignancy."
  },
  {
   "id": "c8",
   "type": "text",
   "front": "List the alarm symptoms.",
   "back": "Persistent vomiting or inability to keep oral intake; severe or progressive abdominal pain; haematemesis; fever; neurological symptoms (severe headache, altered consciousness); dehydration; unintentional weight loss; bilious or feculent vomiting (obstruction); elderly patient; immunocompromised state."
  },
  {
   "id": "c9",
   "type": "text",
   "front": "Which initial tests do you order?",
   "back": "CBC; electrolytes (Na, K, Cl, HCO3); renal function; glucose (DKA); hCG in women of reproductive age; thyroid tests if hyperthyroidism is suspected; urinalysis for ketones. Then as indicated: upper GI endoscopy, ultrasound, CT, ECG (hypokalaemia), cerebral CT, endocrine or toxicological tests."
  },
  {
   "id": "c10",
   "type": "text",
   "front": "When is upper GI endoscopy indicated, and what can it find?",
   "back": "Indications: suspected mucosal lesion, obstruction, complications (upper GI bleeding, oesophagitis, gastritis). It allows immediate biopsy. Findings: ulcers, erosions, masses, chronic GERD or Barrett's oesophagus; pictures show erosions, gastric ulcer, gastric cancer, pylorus obstruction."
  },
  {
   "id": "c11",
   "type": "text",
   "front": "What is the differential diagnosis of vomiting?",
   "back": "Gastro-oesophageal regurgitation: backward flow into the oesophagus without nausea. Rumination syndrome: repeated regurgitation of food into the mouth without nausea."
  },
  {
   "id": "c12",
   "type": "text",
   "front": "List the gastrointestinal causes of acute vomiting.",
   "back": "Gastroenteritis (viral, bacterial, parasitic), food poisoning. Surgical abdomen: peritonitis, appendicitis, cholecystitis, intestinal obstruction. Non-surgical: acute pancreatitis, biliary colic, peptic ulcer, acute gastritis (often NSAIDs)."
  },
  {
   "id": "c13",
   "type": "text",
   "front": "List the non-digestive causes of acute vomiting.",
   "back": "Metabolic/endocrine: DKA, adrenal crisis, hyperthyroidism, hypercalcaemia. Neurological: raised ICP (head injury, stroke, tumour), meningitis, migraine, vestibular disorders. Cardiovascular: MI, aortic dissection. Infectious: sepsis, pyelonephritis. Pregnancy: hyperemesis gravidarum. Electrolytes: hypokalaemia, hyponatraemia. Toxic: chemotherapy, antibiotics, opioids, alcohol, heavy metals. Psychogenic: anxiety, bulimia."
  },
  {
   "id": "c14",
   "type": "text",
   "front": "List the causes of chronic vomiting.",
   "back": "GI: pyloroduodenal stenosis, GERD, gastroparesis (diabetes), chronic pancreatitis, IBS, chronic intestinal pseudo-obstruction, coeliac disease, gastric cancer. Non-GI: chronic renal failure (uraemia), hyperthyroidism, Addison's; chronic migraine, intracranial tumours, chronic raised ICP; long-term NSAIDs, opioids, antibiotics, chronic alcohol; functional, binge-purge, psychogenic vomiting."
  },
  {
   "id": "c15",
   "type": "text",
   "front": "What are the complications of vomiting?",
   "back": "Hydro-electrolytic: dehydration, hypokalaemia, hyponatraemia, metabolic alkalosis. Mechanical: Mallory-Weiss (mucosal tear at the gastro-oesophageal junction, bleeding); Boerhaave (life-threatening oesophageal rupture, leakage into the mediastinum). Infectious: aspiration pneumonia (fever, cough, dyspnoea)."
  }
 ],
 "deeper": [
  {
   "title": "Why vomiting causes metabolic alkalosis and hypokalaemia",
   "html": "<p>Gastric juice is rich in hydrochloric acid. Each vomit removes H+ and Cl-, so bicarbonate accumulates in the blood: metabolic alkalosis. Fluid loss activates aldosterone, which makes the kidney retain sodium and excrete potassium, and alkalosis shifts potassium into cells. Hence the lecture's triad of hypokalaemia, hyponatraemia and metabolic alkalosis, and the ECG to look for the rhythm effects of hypokalaemia.</p><p class='src'>Source: general physiology, linking the lecture's complications and ECG slides.</p>"
  },
  {
   "title": "Mallory-Weiss versus Boerhaave",
   "html": "<p>Both follow forceful vomiting. In <strong>Mallory-Weiss</strong> the tear stays in the mucosa at the gastro-oesophageal junction: the patient vomits blood, usually after several non-bloody vomits, and the bleeding often stops on its own. In <strong>Boerhaave</strong> the oesophageal wall ruptures, contents leak into the mediastinum, and the patient becomes very ill with chest pain and shock: a surgical emergency.</p><p class='src'>Source: the lecture's mechanical complications slide; StatPearls on Mallory-Weiss syndrome.</p>"
  }
 ],
