 "sourceFile": "Dysentery.pdf (Digestive semiology, Pr. Wafaa Khannoussi and Dr Afafe Taiymi)",
 "sourceUrl": "https://drive.google.com/file/d/1liY7Y4Ya9noG8C5ZtUCuXZWakXcYAtfv/view?usp=drivesdk",
 "buildNote": "<strong>Built from the lecture slides.</strong> If your professor says something different, trust your professor.",
 "summary": [
  {
   "id": "s0",
   "title": "The big picture",
   "html": "<p>Dysentery is the rectum sounding an alarm: pain, <strong>false urges</strong> and stools made of <strong>mucus, pus and blood</strong>. The causes range from infection to IBD to cancer, so the key tools are the <strong>rectal exam, sigmoidoscopy and stool tests</strong>.</p>"
  },
  {
   "id": "s1",
   "title": "Symptoms",
   "html": "<p>Cramps focused on the <strong>left iliac fossa</strong> with urgency; <strong>tenesmus</strong>, a painful urge with an empty rectum; false urges; non-faecal stools of mucus, pus and blood; fever, weight loss, dehydration.</p>"
  },
  {
   "id": "s2",
   "title": "Examination and work-up",
   "html": "<p>Look for dehydration, fever, tachycardia, <strong>hypotension</strong> (severe dehydration or sepsis), tenderness, and rectal lesions, blood or mucus.</p><div class='table-wrap'><table class='wide'><thead><tr><th scope='col'>Test</th><th scope='col'>Purpose</th></tr></thead><tbody><tr><th scope='row'>Blood count, CRP, electrolytes</th><td>Systematic</td></tr><tr><th scope='row'>C. difficile toxin</th><td>After recent antibiotics</td></tr><tr><th scope='row'>Stool microscopy</th><td>RBC, WBC, Entamoeba histolytica</td></tr><tr><th scope='row'>Stool culture</th><td>Shigella, Salmonella, Campylobacter, E. coli</td></tr><tr><th scope='row'>Sigmoidoscopy or colonoscopy</th><td>Confirm, biopsy</td></tr><tr><th scope='row'>CT</th><td>Complications, severe or atypical cases</td></tr></tbody></table></div>"
  },
  {
   "id": "s3",
   "title": "Causes",
   "html": "<p>Colorectal cancer and polyps, <strong>IBD</strong>, infectious proctitis (Entamoeba, CMV, E. coli, Salmonella, Shigella), radiation colitis, ischaemic colitis.</p>"
  }
 ],
