 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "Define dysentery.",
   "back": "A clinical syndrome of diffuse abdominal pain, frequent stools with mucus, blood and/or pus, and false urges, reflecting the rectum's reaction to inflammatory, infectious or neoplastic disease."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "What history matters?",
   "back": "Age, occupation, rural or urban setting; GI disease, immunosuppression (HIV, diabetes), tuberculosis, malignancy; surgery; antibiotics, immunosuppressants, chemo- or radiotherapy, antidiarrhoeals; travel; contacts, food and water; family history of colorectal cancer or IBD."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "Describe the symptoms.",
   "back": "Severe cramps along the colon, focused on the left iliac fossa, with urgency; tenesmus (painful urge with empty rectum); false urges; non-faecal stools of mucus, pus and blood. Also fatigue, fever, weight loss, dehydration, vomiting, headache, myalgia, arthralgia."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "What does the exam look for?",
   "back": "Dehydration (dry mucosa, poor turgor, sunken eyes); fever, tachycardia, hypotension (dehydration or sepsis), fast breathing; lower abdominal tenderness, guarding, hyperactive bowel sounds; rectal abscess, fistula, fissure, haemorrhoids, prolapse, mass, blood or mucus; joints, confusion, lymph nodes."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "List the investigations.",
   "back": "Blood count, CRP, electrolytes and renal function; HIV if recurrent; C. difficile toxin after antibiotics. Stool microscopy (RBC, WBC, mucus, Entamoeba) and culture (Shigella, Salmonella, Campylobacter, E. coli). Sigmoidoscopy or colonoscopy with biopsy. CT if severe, atypical or complicated."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "List the causes of dysentery.",
   "back": "Colorectal cancer and polyps; IBD (ulcerative colitis, colonic Crohn's); infectious proctitis (Entamoeba histolytica, CMV, E. coli, Salmonella, Shigella); radiation colitis; ischaemic colitis."
  }
 ],
 "deeper": [
  {
   "title": "Why dysentery is not the same as diarrhoea",
   "html": "<p>Watery diarrhoea usually comes from the small bowel losing fluid. Dysentery comes from an inflamed rectum and colon, so stools are small, frequent and made of mucus, pus and blood, with tenesmus. That distinction points you to the colon and to endoscopy.</p><p class='src'>Source: the lecture's definition and symptoms slides.</p>"
  }
 ],
