 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "How is the thyroid examined?",
   "back": "Inspection: swelling (the normal thyroid is not visible), inflammation, dilated cervical veins. Palpation of the gland. Auscultation: a bruit indicates high blood flow in hyperthyroidism, sometimes with a thrill."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "How is thyroid function evaluated?",
   "back": "TSH, free T4 and free T3. Ultrasound describes size, structure, volume, nodules (size, solid or liquid, margins, vascularity, micro- or macrocalcifications) and lymph nodes. Scintigraphy shows uptake."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "List the signs of hyperthyroidism.",
   "back": "General: fatigue, weight loss despite increased appetite. Cardiovascular: resting tachycardia, palpitations, exertional dyspnoea, loud heart sounds, systolic murmur, raised systolic BP. Hot sweaty skin, heat intolerance. Fine tremor, hyperkinesia, hyperreflexia, amyotrophy, weakness. Soft stools. Emotional lability, irritability, insomnia. Eyes: lid retraction, lid lag, rare blinking, eyelid tremor."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "Describe Graves' disease.",
   "back": "The commonest cause of hyperthyroidism: autoimmune, genetically predisposed, mostly women aged 20 to 40, relapsing and remitting. TSH receptor antibodies are highly specific; ultrasound shows enlarged volume with increased vascularity; scintigraphy shows diffuse homogeneous uptake. Diagnosis: thyrotoxicosis + goitre + exophthalmos."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "Describe Graves' ophthalmopathy.",
   "back": "Inflammation of orbital muscles, periocular tissue and retro-orbital fat: lid retraction, exophthalmos, chemosis, scleral injection, diplopia, muscle dysfunction, and reduced acuity from optic neuropathy."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "Toxic adenoma versus toxic multinodular goitre.",
   "back": "Toxic adenoma: a single hypersecreting nodule, thyrotoxicosis without eye signs, a hot nodule on scintigraphy with suppressed contralateral lobe. Toxic multinodular goitre: older patients with long-standing goitre becoming toxic; look for compression; multiple hot nodules or patchy uptake."
  },
  {
   "id": "c6",
   "type": "text",
   "front": "Hyperthyroidism versus thyrotoxicosis without it.",
   "back": "Hyperthyroidism: Graves', toxic nodular goitre, toxic adenoma, Jod-Basedow, metastatic follicular cancer, trophoblastic tumours. Thyrotoxicosis without hyperthyroidism: subacute and silent thyroiditis, ectopic thyroid, struma ovarii. Thyroiditis releases stored hormone transiently."
  },
  {
   "id": "c7",
   "type": "text",
   "front": "Define hypothyroidism and its causes.",
   "back": "Deficient thyroid hormone slowing metabolism; primary or secondary (pituitary). Causes: iatrogenic (thyroidectomy, radioiodine, irradiation, drugs such as lithium and amiodarone), thyroiditis (Hashimoto's, de Quervain, postpartum, Riedel), iodine deficiency, congenital, central."
  },
  {
   "id": "c8",
   "type": "text",
   "front": "Give the findings of hypothyroidism.",
   "back": "Hypometabolism: physical, psychological, intellectual and sexual asthenia. TSH markedly raised, FT4 and FT3 low. Organ effects: macrocytic anaemia, dilutional hyponatraemia, hypercholesterolaemia, hyperprolactinaemia. Anti-TPO and anti-Tg antibodies for aetiology."
  },
  {
   "id": "c9",
   "type": "text",
   "front": "Name the complications of hypothyroidism.",
   "back": "Myxoedema coma: rare end stage in the elderly, with stupor, hypothermia, hypoglycaemia, hyponatraemia, hypoventilation, shock and death. Cardiovascular: myxoedema cardiomyopathy and heart failure, pericardial effusion, coronary disease from high cholesterol."
  },
  {
   "id": "c10",
   "type": "text",
   "front": "How are goitre and nodules evaluated?",
   "back": "Normal thyroid: height 4 to 6 cm, width and thickness 1.5 to 2.5 cm; goitre if thickness over 2.5 cm or volume over 18 cm³ (women) or 20 cm³ (men). 90 to 95 percent of lumps are benign. Red flags: hoarseness, nodes, stridor. Ultrasound U1 to U5; FNAC for U3 to U5. Cancer work-up: palpation, ultrasound, hormones and calcitonin, FNA, histology."
  }
 ],
 "deeper": [
  {
   "title": "Why TSH moves opposite to thyroid hormone",
   "html": "<p>TSH is controlled by negative feedback: when thyroid hormone is high, the pituitary shuts TSH off; when it is low, TSH rises to push the gland harder. So in primary thyroid disease TSH moves the opposite way and is the most sensitive single test. Only in pituitary (central) disease do both fall together.</p><p class='src'>Source: the lecture's thyroid function slides, with standard physiology.</p>"
  }
 ],
