 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "Cushing's disease versus syndrome.",
   "back": "Cushing's syndrome is cortisol excess of any cause. Cushing's disease is specifically a pituitary ACTH-secreting source."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "List the clinical signs of hypercortisolism.",
   "back": "Weight excess with truncal obesity, moon face and particular fat deposits; purple striae; hypertension; diabetes or prediabetes; acne; limb muscle atrophy; depression with suicide risk, or euphoria and delirium; thrombosis risk; osteoporosis; hirsutism and menstrual troubles in women; erectile dysfunction in men."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "How is cortisol excess classified?",
   "back": "By ACTH: ACTH-dependent (high ACTH) from a pituitary or ectopic source; ACTH-independent (low ACTH) from an adrenal source."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "What does imaging show?",
   "back": "Adrenal CT: gland structure and size, tumour cause, adenoma size and lipid content, tumour extension. MIBG scintigraphy: functional evaluation of catecholamine-secreting tissue, unilateral secretion (adenoma or hyperplasia) or ectopic secretion; paragangliomas are possible along the sympathetic chain."
  }
 ],
 "deeper": [
  {
   "title": "Why low ACTH points to the adrenal",
   "html": "<p>Cortisol normally switches ACTH off by feedback. If an adrenal tumour makes cortisol on its own, ACTH is suppressed. If ACTH is high despite high cortisol, something is driving the adrenals: a pituitary or ectopic source.</p><p class='src'>Source: the lecture's cortisol excess algorithm, with standard physiology.</p>"
  }
 ],
