 "id": "semio-endo-diabetes",
 "subject": "semio",
 "group": "Endocrine",
 "title": "Diabetes semiology",
 "sourceFile": "DIABETES SEMIOLOGY 2026.pdf, converted from the PowerPoint (Endocrinology semiology, Pr. Ioana Hristov, 2026-2027)",
 "sourceUrl": "https://drive.google.com/file/d/11uvui5y90UA34VC9GRAY9zA3enYF4vgU/view?usp=drivesdk",
 "sourcePdf": "files/src/semio-endo-diabetes.pdf",
 "buildNote": "<strong>Built from the lecture slides.</strong> On the 10 November midterm: only the symptoms that reveal diabetes. If your professor says something different, trust your professor.",
 "summary": [
  {
   "id": "s0",
   "title": "The big picture",
   "html": "<p>Diabetes is <strong>chronic hyperglycaemia</strong> from an absolute or relative lack of insulin <strong>secretion</strong> and/or insulin <strong>action</strong> (insulin resistance). Normal: fasting glucose <strong>under 1.10 g/L</strong>, and under 1.40 g/L 2 hours after an OGTT.</p><p class='mid-only'>On the midterm: <strong>how diabetes reveals itself</strong> (sections 2 to 4).</p>"
  },
  {
   "id": "s1",
   "title": "How diabetes is discovered",
   "html": "<p>Three circumstances: <strong>by chance</strong> (a routine test), from <strong>symptoms of hyperglycaemia</strong>, or at an <strong>acute or chronic complication</strong>. Type 2 is diagnosed on average <strong>2 to 3 years</strong> after it really starts.</p>"
  },
  {
   "id": "s2",
   "title": "The symptoms",
   "html": "<p><strong>The hyperglycaemia syndrome:</strong> <strong>polyuria</strong> (glycosuria causes an osmotic diuresis), <strong>polydipsia</strong> (because of the polyuria), <strong>weight loss</strong> (no insulin, so lipolysis; cells are in a fasting state) and <strong>compensatory polyphagia</strong>.</p><ul><li>Also: <strong>blurred vision</strong>, fatigue (lethargy, even stupor), slow-healing cuts and sores, nausea or abdominal pain, <strong>paresthesia</strong> (neuropathy), frequent urination at night.</li><li>Red flags of ketosis (more typical of type 1): <strong>acetone breath</strong>, <strong>Kussmaul breathing</strong>, abdominal pain, nausea and vomiting.</li></ul><p><strong>Examination:</strong> capillary blood glucose; urine strip (glucose appears in urine once blood glucose passes <strong>1.8 g/L</strong>, the renal threshold); signs of dehydration; weight, height and BMI; signs of infection; look for complications.</p>"
  },
  {
   "id": "s3",
   "title": "Diagnostic criteria",
   "html": "<ol><li>Fasting plasma glucose <strong>≥ 1.26 g/L (7.0 mmol/L) on 2 samples</strong>, or</li><li>2-hour glucose <strong>≥ 2 g/L (11.1 mmol/L)</strong> during a 75 g OGTT, or</li><li><strong>HbA1c ≥ 6.5%</strong> (48 mmol/mol), or</li><li>Classic symptoms with a <strong>random glucose ≥ 2 g/L</strong>.</li></ol><p>Prediabetes: HbA1c 5.7 to 6.4%, fasting 1.00 to 1.25 g/L, 2-hour OGTT 1.40 to 1.99 g/L.</p>"
  },
  {
   "id": "s4",
   "title": "Type 1 or type 2?",
   "html": "<div class='table-wrap'><table class='wide'><thead><tr><th scope='col'></th><th scope='col'>Type 1</th><th scope='col'>Type 2</th></tr></thead><tbody><tr><th scope='row'>Frequency</th><td>10 to 15%</td><td><strong>85 to 90%</strong></td></tr><tr><th scope='row'>Age</th><td>Young (under 40)</td><td>After 40</td></tr><tr><th scope='row'>Onset</th><td><strong>Acute</strong></td><td>Progressive</td></tr><tr><th scope='row'>Body</th><td>Normal or thin</td><td>Overweight or obese</td></tr><tr><th scope='row'>Family history</th><td>+</td><td>+++</td></tr><tr><th scope='row'>Hyperglycaemia symptoms</th><td>+++</td><td>Often none</td></tr><tr><th scope='row'>Ketosis</th><td>Frequent, can reveal it (DKA)</td><td>Absent (DKA only with an added illness)</td></tr><tr><th scope='row'>Autoimmunity</th><td>Autoantibodies, other autoimmune disease</td><td>No</td></tr><tr><th scope='row'>Cardiovascular risk factors</th><td>No</td><td>Yes (hypertension, dyslipidaemia...)</td></tr><tr><th scope='row'>Insulin</th><td>Absent: insulin for life</td><td>Still made</td></tr><tr><th scope='row'>Complication check</th><td>Some years after diagnosis</td><td>At diagnosis</td></tr></tbody></table></div>"
  },
  {
   "id": "s5",
   "title": "Complications (not on this midterm)",
   "html": "<ul><li><strong>Acute:</strong> diabetic ketoacidosis (polyuria, thirst, then abdominal pain, vomiting, fruity breath, dehydration, Kussmaul breathing, drowsiness to coma; ketonaemia ≥ 3 mmol/L, glucose over 2.5 g/L); <strong>hypoglycaemia</strong> (≤ 0.7 g/L; Whipple triad; adrenergic signs such as tremor, sweating, palpitations, hunger, then neuroglycopenic signs such as confusion, seizures, coma); hyperosmolar state; lactic acidosis.</li><li><strong>Chronic microvascular:</strong> retinopathy (often silent until haemorrhage or detachment: screen with fundoscopy), nephropathy (albumin-to-creatinine ratio, GFR), neuropathy (monofilament, 128 Hz tuning fork, reflexes, DN4; autonomic: orthostatic hypotension, resting tachycardia, gastroparesis, erectile dysfunction; Charcot foot, foot ulcers).</li><li><strong>Chronic macrovascular:</strong> coronary disease (often atypical or silent), stroke, peripheral artery disease (lost pulses, cold pale skin, ankle-brachial index).</li></ul>"
  }
 ],
