 "deeper": [
  {
   "title": "Why thirst follows the urine, not the other way round",
   "html": "<p>Above about 1.8 g/L the kidney can no longer reabsorb all the filtered glucose. The glucose left in the tubule holds water with it (osmotic diuresis), so large volumes of urine are passed. The water loss then triggers thirst. In primary polydipsia the order is reversed: drinking comes first and the urine follows.</p><p class='src'>Source: the lecture's history and examination slides, with standard renal physiology.</p>"
  }
 ],
